package main
import("bytes";"encoding/json";"fmt";"io";"mime/multipart";"net/http";"os";"path/filepath")
func main(){var b bytes.Buffer; w:=multipart.NewWriter(&b); vals:=map[string]string{"project_slug":os.Getenv("MATCHALL_PROJECT"),"version":os.Getenv("MATCHALL_VERSION"),"channel":"stable","os_name":"any","arch":"any","rollout_percentage":"100"};for k,v:=range vals{_ = w.WriteField(k,v)};p:=os.Getenv("MATCHALL_ARTIFACT");f,_:=w.CreateFormFile("upload",filepath.Base(p));in,_:=os.Open(p);_,_=io.Copy(f,in);_=w.Close();u:=os.Getenv("MATCHALL_MIRRORS_URL");if u==""{u="https://mirrors.maximoraverse.org"};req,_:=http.NewRequest("POST",u+"/api/v1/developer/releases/upload",&b);req.Header.Set("Content-Type",w.FormDataContentType());req.Header.Set("Authorization","Bearer "+os.Getenv("MATCHALL_MIRRORS_TOKEN"));r,e:=http.DefaultClient.Do(req);if e!=nil{panic(e)};defer r.Body.Close();var out any;_=json.NewDecoder(r.Body).Decode(&out);if r.StatusCode>=300{panic(fmt.Sprint(out))};fmt.Printf("%v\n",out)}
